#include "tap.h"
#include <stdlib.h>
#include <string.h>
int rc_tap_next(rc_tap *t,uint32_t *cycles){if(!t->image||t->position>=t->image->size)return 0;const uint8_t *p=t->image->data;const unsigned v=p[t->position++];if(v)*cycles=v*8u;else if(!t->version)*cycles=2048;else {if(t->image->size-t->position<3)return 0;*cycles=p[t->position]|(uint32_t)p[t->position+1]<<8|(uint32_t)p[t->position+2]<<16;t->position+=3;}return *cycles!=0;}
/* The pulses run to the end of the file. Some early TAP files carry a wrong
 * data length in their header; the length is not needed to play them. */
int rc_tap_open(rc_tap *t,const uint8_t *data,size_t size,char *error,size_t cap){memset(t,0,sizeof *t);if(size<20||size>RC_MEDIA_LIMIT||memcmp(data,"C64-TAPE-RAW",12)||data[12]>1)return rc_image_error(error,cap,"Invalid TAP header");t->image=rc_media_from("",data,size);if(!t->image)return rc_image_error(error,cap,"Out of memory");t->version=data[12];t->position=20;uint32_t pulse;while(t->position<size)if(!rc_tap_next(t,&pulse)){rc_tap_close(t);return rc_image_error(error,cap,"Truncated or zero-length TAP pulse");}t->position=20;return 1;}
int rc_tap_create(rc_tap *t,unsigned version,char *error,size_t cap){if(version>1)return rc_image_error(error,cap,"Unsupported TAP version");uint8_t data[20]={0};memcpy(data,"C64-TAPE-RAW",12);data[12]=(uint8_t)version;const int ok=rc_tap_open(t,data,20,error,cap);if(ok)t->image->writable=1;return ok;}
static int upgrade(rc_tap *t){size_t zeros=0,before=0;for(size_t i=20;i<t->image->size;++i)if(!t->image->data[i]){++zeros;if(i<t->position)++before;}if(zeros>(RC_MEDIA_LIMIT-t->image->size)/3)return 0;const size_t n=t->image->size+zeros*3;uint8_t *data=malloc(n);if(!data)return 0;memcpy(data,t->image->data,20);size_t pos=20;for(size_t i=20;i<t->image->size;++i){const uint8_t byte=t->image->data[i];data[pos++]=byte;if(!byte){data[pos++]=0;data[pos++]=8;data[pos++]=0;}}free(t->image->data);t->image->data=data;t->image->size=n;t->position+=before*3;t->version=data[12]=1;rc_image_put32(data+16,(uint32_t)(n-20));t->image->dirty=1;return 1;}
int rc_tap_append(rc_tap *t,uint32_t cycles,char *error,size_t cap){if(!t->image||!t->image->writable)return rc_image_error(error,cap,"TAP is read-only");if(!cycles||cycles>0xffffffu)return rc_image_error(error,cap,"TAP pulse exceeds its 24-bit range");if(!t->version&&((cycles&7u)||cycles>2048)){if(!upgrade(t))return rc_image_error(error,cap,"Cannot upgrade TAP to version 1");}const size_t count=cycles<=2040&&!(cycles&7u)?1:t->version?4:1;const size_t old=t->image->size;if(count>RC_MEDIA_LIMIT-old||!rc_media_resize(t->image,old+count))return rc_image_error(error,cap,"Cannot grow TAP image");uint8_t *p=t->image->data+old;if(count==1)p[0]=cycles==2048?0:(uint8_t)(cycles/8u);else {p[0]=0;p[1]=(uint8_t)cycles;p[2]=(uint8_t)(cycles>>8);p[3]=(uint8_t)(cycles>>16);}rc_image_put32(t->image->data+16,(uint32_t)(t->image->size-20));t->image->dirty=1;return 1;}
void rc_tap_rewind(rc_tap *t){t->position=20;}
void rc_tap_close(rc_tap *t){rc_media_close(t->image);memset(t,0,sizeof *t);}
void rc_tap_save(const rc_tap *t,rc_state_writer *w){rc_sw_u32(w,1);rc_sw_u32(w,(uint32_t)t->position);rc_image_save(t->image,w);}
int rc_tap_load(rc_tap *t,rc_state_reader *r){if(r->end-r->at<8||rc_sr_u32(r)!=1)return 0;const size_t position=rc_sr_u32(r);rc_media *m=rc_image_load(r);if(!m)return 0;rc_tap next;char error[128];if(!rc_tap_open(&next,m->data,m->size,error,sizeof error)){rc_media_close(m);return 0;}if(position<20||position>m->size){rc_tap_close(&next);rc_media_close(m);return 0;}uint32_t pulse;while(next.position<position)if(!rc_tap_next(&next,&pulse))break;if(next.position!=position){rc_tap_close(&next);rc_media_close(m);return 0;}rc_media_close(next.image);next.image=m;rc_tap_close(t);*t=next;return 1;}
